//! 🎟️ Shared original feature and shaping cases retain physical authority through every child.
use super::*;
use semio_framework_2d_text_font::work::FontWorkLedger;
use semio_framework_value::{RetainedCloneGrant,RetirementDemand};
fn run(mut advance:impl FnMut(&mut FontWorkLedger)->Result<FontProgress,&'static str>){let mut demand=RetirementDemand::default();for _ in 0..100000{let mut denied=FontWorkLedger::new(RetainedCloneGrant{maximum_items:0,maximum_copy_bytes:0,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:0});assert!(!advance(&mut denied).unwrap().done);assert_eq!((denied.receipt().copied_bytes,denied.receipt().retained_capacity_bytes),(0,0));let mut work=FontWorkLedger::new(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth});let(progress,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||advance(&mut work).unwrap());assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,work.receipt().retained_capacity_bytes);assert_eq!(heap.released_bytes,work.receipt().released_bytes);demand=if work.blocked(){work.next_demand()}else{RetirementDemand::default()};if progress.done{return;}}panic!("shape authority fixture stalled")}
#[test]
fn original_lookup_table_authority_matches_independent_ttf_parser(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let features=fixture["features"].as_array().unwrap().iter().map(|tag|tag.as_str().unwrap().as_bytes().try_into().unwrap()).collect::<Vec<[u8;4]>>();for source in semio_framework_2d_text_font_catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());run(|work|admission.advance(1,work));let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(source.bytes.0,0).unwrap();for substitution in[true,false]{let table=if substitution{parser.tables().gsub}else{parser.tables().gpos};let language=table.and_then(|table|table.scripts.find(ttf_parser::Tag::from_bytes(b"latn")).or_else(||table.scripts.find(ttf_parser::Tag::from_bytes(b"DFLT"))).and_then(|script|script.default_language));let mut expected=std::collections::BTreeSet::new();if let(Some(table),Some(language))=(table,language){for index in language.required_feature.into_iter().chain(language.feature_indices){let feature=table.features.get(index).unwrap();if language.required_feature==Some(index)||features.iter().any(|tag|feature.tag==ttf_parser::Tag::from_bytes(tag)){expected.extend(feature.lookup_indices);}}}let mut plan=crate::FontLookupPlanCursor::new(font.face,substitution,*b"latn",&features,1000000000);run(|work|plan.advance(source.bytes.0,1,work));assert_eq!(plan.result().unwrap().iter().map(|row|row.index).collect::<Vec<_>>(),expected.into_iter().collect::<Vec<_>>());close(plan);}close(font);close(admission);}}
#[test]
fn original_complete_shaping_pipeline_matches_independent_rustybuzz(){use semio_framework_2d_text_font_shape_unicode::{*,normalize::UnicodeNormalizationCursor,cluster::UnicodeGraphemeCursor};let fixture:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let mut admission=UnicodeDataAdmissionJob::new(StaticFontBytes(UNICODE_BYTES),1000000);run(|work|admission.advance(1,work));let data=admission.take_result().unwrap();let mut fonts=Vec::new();for source in semio_framework_2d_text_font_catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());while !admission.advance(4096,&mut fixture_work()).unwrap().done{}fonts.push(admission.take_result().unwrap());close(admission);}let mut limits=FontOutlineLimits::default();limits.max_glyphs=4096;for row in fixture["textCases"].as_array().unwrap(){let text=row["text"].as_str().unwrap();let mut normalization=UnicodeNormalizationCursor::new(data.layout,UNICODE_BYTES,text,1048576,1000000000);run(|work|normalization.advance(UNICODE_BYTES,text,1,work));let source=normalization.take_result().unwrap();let mut cluster=UnicodeGraphemeCursor::new(data.layout,UNICODE_BYTES,&source,1000000000);run(|work|cluster.advance(UNICODE_BYTES,&source,1,work));let clusters=cluster.take_result().unwrap();for bounds in clusters.iter(){let mut selection=crate::face::FontClusterFaceCursor::new(data.layout,UNICODE_BYTES,&source,&fonts,*bounds,0,limits);run(|work|selection.advance(UNICODE_BYTES,&source,&fonts,1,work));let mapping=selection.take_result().unwrap();let index=mapping.face;let text=source.iter().skip(bounds.start).take(bounds.end-bounds.start).map(|s|char::from_u32(s.scalar).unwrap()).collect::<String>();let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(&text);buffer.guess_segment_properties();let foreign=rustybuzz::shape(&rustybuzz::Face::from_slice(fonts[index].source.0,0).unwrap(),&[],buffer);let expected=foreign.glyph_infos().iter().map(|glyph|glyph.glyph_id as u16).collect::<Vec<_>>();let mut layout=crate::layout::FontClusterLayoutCursor::new(fonts[index].face,mapping,limits);run(|work|layout.advance(fonts[index].source.0,1,work));let output=layout.take_result().unwrap();assert_eq!(output.glyphs.iter().map(|g|g.glyph).collect::<Vec<_>>(),expected);close(output);close(layout);close(selection);}close(clusters);close(cluster);close(source);close(normalization);}close(fonts);close(data);close(admission);}
